public void testEnhancementInterfaces() throws Exception {
    ContentItem ci = wrapAsContentItem("urn:contentItem-" + EnhancementEngineHelper.randomUUID(), SINGLE_SENTENCE);
    UriRef ciUri = new UriRef(ci.getId());
